#!/usr/bin/env python3
"""Check that APKs package the Endpoint Scanner binaries generated by Gradle."""
import hashlib
import sys
import zipfile
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
LIBS = ROOT / "app" / "build" / "generated" / "endpointScanner" / "jniLibs"
ABIS = ("arm64-v8a", "armeabi-v7a", "x86", "x86_64")


def scanner_hashes() -> dict[str, str]:
    missing = [abi for abi in ABIS if not (LIBS / abi / "libendpointscanner.so").is_file()]
    if missing:
        raise SystemExit(
            "Endpoint Scanner binaries are missing. Build or run the Android app in Android Studio first; "
            f"missing ABI(s): {', '.join(missing)}"
        )
    return {
        abi: hashlib.sha256((LIBS / abi / "libendpointscanner.so").read_bytes()).hexdigest()
        for abi in ABIS
    }


def check(path: Path, expected: dict[str, str]) -> None:
    found = set()
    with zipfile.ZipFile(path) as archive:
        for name in archive.namelist():
            parts = name.split("/")
            if len(parts) != 3 or parts[0] != "lib" or parts[2] != "libendpointscanner.so":
                continue
            abi = parts[1]
            if abi not in EXPECTED:
                raise SystemExit(f"FAIL: unexpected Endpoint Scanner ABI in {path.name}: {abi}")
            actual = hashlib.sha256(archive.read(name)).hexdigest()
            if actual != EXPECTED[abi]:
                raise SystemExit(f"FAIL: APK scanner differs from source for {abi}: {path.name}")
            found.add(abi)
    if not found:
        raise SystemExit(f"FAIL: {path.name} does not package the Endpoint Scanner CLI")
    print(f"PASS: {path.name}: Endpoint Scanner CLI matches source for {', '.join(sorted(found))}")


if __name__ == "__main__":
    if len(sys.argv) < 2:
        raise SystemExit("Usage: python3 tools/verify_endpoint_scanner_apk.py <APK> [<APK>...]")
    expected = scanner_hashes()
    for value in sys.argv[1:]:
        check(Path(value), expected)
